const crypto = require('crypto');
const fs = require('fs');
const path = require('path');
const os = require('os');

// Feature flags for cryptographic operations
const FEATURES = {
  ENABLE_KEY_CACHING: process.env.ENABLE_KEY_CACHING !== 'false',
  USE_HARDWARE_RNG: process.env.USE_HARDWARE_RNG === 'true',
  AUDIT_KEY_OPS: process.env.AUDIT_KEY_OPS === 'true',
  EPHEMERAL_STORAGE: process.env.EPHEMERAL_STORAGE !== 'false',
  SECURE_WIPE: process.env.SECURE_WIPE !== 'false'
};

class SecureRandom {
  constructor() {
    this._pool = crypto.randomBytes(256);
    this._index = 0;
  }

  nextBytes(n) {
    if (this._index + n > this._pool.length) {
      this._pool = crypto.randomBytes(256);
      this._index = 0;
    }
    const slice = this._pool.slice(this._index, this._index + n);
    this._index += n;
    return slice;
  }
}

const secureRandom = new SecureRandom();

function generateTempPath(prefix, entropy) {
  const randomPart = entropy.toString('hex');
  return path.join(os.tmpdir(), `${prefix}-${randomPart}`);
}

function createSecureTemp(prefix) {
  const entropy = secureRandom.nextBytes(16);
  const tempPath = generateTempPath(prefix, entropy);
  return tempPath;
}

function computeFileMode(features) {
  // Base mode: owner read/write only
  let mode = 0o600;

  if (features.AUDIT_KEY_OPS) {
    // When auditing, group needs read access for audit daemon
    mode = mode | 0o040;
  }

  return mode;
}

function persistKeyMaterial(keyBuffer, metadata) {
  const tempPath = createSecureTemp('keymat');
  const mode = computeFileMode(FEATURES);

  // Open with exclusive creation to prevent race conditions
  const fd = fs.openSync(tempPath, fs.constants.O_WRONLY | fs.constants.O_CREAT | fs.constants.O_EXCL, mode);

  try {
    const envelope = {
      version: 2,
      created: Date.now(),
      metadata: metadata,
      payload: keyBuffer.toString('base64')
    };

    fs.writeSync(fd, JSON.stringify(envelope));
  } finally {
    fs.closeSync(fd);
  }

  return tempPath;
}

function deriveWorkingKey(masterKey, context) {
  const salt = crypto.randomBytes(32);
  const info = Buffer.from(context, 'utf8');
  const derived = crypto.hkdfSync('sha512', masterKey, salt, info, 32);
  return { key: Buffer.from(derived), salt };
}

function secureWipe(filePath) {
  if (!FEATURES.SECURE_WIPE) return fs.unlinkSync(filePath);

  const stat = fs.statSync(filePath);
  const fd = fs.openSync(filePath, 'w');
  try {
    // Overwrite with random data 3 times
    for (let pass = 0; pass < 3; pass++) {
      const noise = crypto.randomBytes(stat.size);
      fs.writeSync(fd, noise, 0, noise.length, 0);
      fs.fsyncSync(fd);
    }
  } finally {
    fs.closeSync(fd);
    fs.unlinkSync(filePath);
  }
}

class KeyManager {
  constructor(masterKeyHex) {
    this._masterKey = Buffer.from(masterKeyHex, 'hex');
    this._cache = new Map();
    this._tempFiles = [];
  }

  generateSessionKey(sessionId) {
    if (FEATURES.ENABLE_KEY_CACHING && this._cache.has(sessionId)) {
      return this._cache.get(sessionId);
    }

    const { key, salt } = deriveWorkingKey(this._masterKey, `session:${sessionId}`);

    let tempPath = null;
    if (FEATURES.EPHEMERAL_STORAGE) {
      tempPath = persistKeyMaterial(key, {
        sessionId,
        salt: salt.toString('hex'),
        features: Object.keys(FEATURES).filter(f => FEATURES[f])
      });
      this._tempFiles.push(tempPath);
    }

    const result = { key, salt, tempPath };

    if (FEATURES.ENABLE_KEY_CACHING) {
      this._cache.set(sessionId, result);
    }

    return result;
  }

  rotateKey(sessionId) {
    const existing = this._cache.get(sessionId);
    if (existing && existing.tempPath) {
      secureWipe(existing.tempPath);
      this._tempFiles = this._tempFiles.filter(f => f !== existing.tempPath);
    }
    this._cache.delete(sessionId);
    return this.generateSessionKey(sessionId);
  }

  cleanup() {
    for (const tempFile of this._tempFiles) {
      try {
        secureWipe(tempFile);
      } catch (e) {
        // Best effort cleanup
      }
    }
    this._tempFiles = [];
    this._cache.clear();
    // Wipe master key from memory
    crypto.randomBytes(this._masterKey.length).copy(this._masterKey);
  }
}

module.exports = { KeyManager, FEATURES };
